// A simple Matrix type backed by Vec<Vec<T>>.
pub type Matrix<T> = Vec<Vec<T>>;

pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(!a.is_empty(), "input array must have positive length");
    assert!(shape.len() == 2, "shape must have length 2");

    let r = shape[0] as usize;
    let c = shape[1] as usize;

    assert!(r > 0 && c > 0, "shape entries must be positive");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must equal R or C (got len={}, R={}, C={})",
        n,
        r,
        c
    );

    // If R matches, treat as column vector: M[i][j] = a[i].
    if n == r {
        let mut ret: Matrix<i8> = Vec::with_capacity(r);
        for i in 0..r {
            let val = a[i];
            ret.push(vec![val; c]);
        }
        ret
    } else {
        // Otherwise C matches, treat as row vector: M[i][j] = a[j].
        let mut ret: Matrix<i8> = Vec::with_capacity(r);
        for _ in 0..r {
            ret.push(a.clone());
        }
        ret
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn broadcast_as_column_vector() {
        let a = vec![1i8, -2, 3];
        let shape = vec![3u8, 4u8];
        let m = broadcast(a, shape);
        assert_eq!(m.len(), 3);
        assert_eq!(m[0], vec![1, 1, 1, 1]);
        assert_eq!(m[1], vec![-2, -2, -2, -2]);
        assert_eq!(m[2], vec![3, 3, 3, 3]);
    }

    #[test]
    fn broadcast_as_row_vector() {
        let a = vec![7i8, 8, -9, 10];
        let shape = vec![3u8, 4u8];
        let m = broadcast(a.clone(), shape);
        assert_eq!(m.len(), 3);
        assert_eq!(m[0], a);
        assert_eq!(m[1], vec![7, 8, -9, 10]);
        assert_eq!(m[2], vec![7, 8, -9, 10]);
    }
}